"""TSV serialization validation utility."""
from typing import List, Dict

def parse_tsv_line(line: str) -> List[str]:
    """Split raw tab-delimited record into field tokens, handling RFC 4180 quotes."""
    fields = []
    current_field = []
    in_quote = False
    escape_next = False

    for char in line:
        if escape_next:
            current_field.append(char)
            escape_next = False
        elif char == '\\':
            escape_next = True
        elif char == '"':
            in_quote = not in_quote
        elif char == '\t' and not in_quote:
            fields.append(''.join(current_field))
            current_field = []
        else:
            current_field.append(char)

    fields.append(''.join(current_field))
    return fields

def count_tsv_fields(line: str) -> int:
    """Count number of tab-delimited columns in row."""
    return len(parse_tsv_line(line))

def join_tsv_fields(fields: List[str]) -> str:
    """Join list of string fields using single tab delimiter, escaping necessary characters."""
    escaped_fields = []
    for field in fields:
        if '\t' in field or '"' in field or '\n' in field or '\r' in field:
            field = field.replace('"', '""')
            field = f'"{field}"'
        escaped_fields.append(field)
    return "\t".join(escaped_fields)

def validate_tsv_columns(line: str, expected_cols: int) -> bool:
    """Verify line conforms to expected column count."""
    return count_tsv_fields(line) == expected_cols

def escape_tsv_cell(val: str) -> str:
    """Escape control characters for safe single-cell embedding."""
    val = val.replace("\\", "\\\\")
    val = val.replace("\r", "\\r")
    val = val.replace("\n", "\\n")
    val = val.replace("\t", "\\t")
    if '"' in val:
        val = val.replace('"', '""')
        val = f'"{val}"'
    return val

def sanitize_tsv_record(line: str) -> str:
    """Trim trailing newline or carriage return from line."""
    return line.rstrip("\r\n")

def is_comment_line(line: str) -> bool:
    """Check if row begins with comment prefix hash."""
    return line.startswith("#")
